// Package loadtest contains the flag fixtures, the exporter behaviours and the soak harness
// used to measure the throughput and the memory stability of semaphore.
// See README.md in this directory.
package loadtest

import (
	"fmt"
	"strings"
)

const (
	// largeListSize is the number of items of the large "in" list of the large flag.
	largeListSize = 500
)

// Scenarios returns the list of flag scenarios generated by FlagsYAML.
func Scenarios() []string {
	return []string{
		"norule", "rule", "multirule", "jsonlogic", "percentage",
		"progressive", "scheduled", "largein",
	}
}

// Types returns the list of flag value types generated by FlagsYAML.
func Types() []string { return []string{"bool", "string", "json"} }

// FlagKey returns the key of the generated flag for a scenario, a type and the tracking mode.
func FlagKey(scenario, typ string, track bool) string {
	if track {
		return fmt.Sprintf("%s-%s-track", scenario, typ)
	}

	return fmt.Sprintf("%s-%s-notrack", scenario, typ)
}

func variations(typ string) string {
	switch typ {
	case "string":
		return "    A: \"a\"\n    B: \"b\"\n"
	case "json":
		return "    A: {color: blue, size: 3, tags: [x, y]}\n    B: {color: red, size: 1, tags: []}\n"
	default:
		return "    A: true\n    B: false\n"
	}
}

func largeList(n int) string {
	items := make([]string, n)
	for i := range items {
		items[i] = fmt.Sprintf("%q", fmt.Sprintf("user-%d", i))
	}

	return "[" + strings.Join(items, ",") + "]"
}

func scenarioBody(scenario string) string {
	switch scenario {
	case "rule":
		return "  targeting:\n    - query: key eq \"user-5\"\n      variation: A\n  defaultRule:\n    variation: B\n"
	case "multirule":
		return "  targeting:\n" +
			"    - name: r1\n      query: country eq \"FR\" and age gt 90\n      variation: A\n" +
			"    - name: r2\n      query: plan eq \"enterprise\" and region eq \"nowhere\"\n      variation: A\n" +
			"    - name: r3\n      query: email co \"@nowhere.test\"\n      variation: A\n" +
			"    - name: r4\n      query: key eq \"user-5\" or key eq \"user-36\"\n      variation: A\n" +
			"  defaultRule:\n    variation: B\n"
	case "jsonlogic":
		return "  targeting:\n" +
			"    - query: '{\"in\": [{\"var\": \"key\"}, [\"user-5\", \"user-36\"]]}'\n      variation: A\n" +
			"  defaultRule:\n    variation: B\n"
	case "percentage":
		return "  defaultRule:\n    percentage:\n      A: 50\n      B: 50\n"
	case "progressive":
		return "  defaultRule:\n    progressiveRollout:\n      initial:\n        variation: B\n        percentage: 0\n" +
			"        date: 2000-01-01T00:00:00Z\n      end:\n        variation: A\n        percentage: 100\n" +
			"        date: 2050-01-01T00:00:00Z\n"
	case "scheduled":
		return "  defaultRule:\n    percentage:\n      A: 0\n      B: 100\n  scheduledRollout:\n" +
			"    - date: 2000-01-01T00:00:00Z\n      defaultRule:\n        percentage:\n          A: 50\n          B: 50\n" +
			"    - date: 2100-01-01T00:00:00Z\n      defaultRule:\n        percentage:\n          A: 100\n          B: 0\n"
	case "largein":
		return "  targeting:\n    - query: key in " + largeList(largeListSize) + "\n      variation: A\n" +
			"  defaultRule:\n    variation: B\n"
	default: // norule
		return "  defaultRule:\n    variation: A\n"
	}
}

// FlagsYAML returns a flag configuration (YAML) with one flag per scenario, type and tracking
// mode. Keys are given by FlagKey.
func FlagsYAML() string {
	var builder strings.Builder

	for _, sc := range Scenarios() {
		for _, typ := range Types() {
			for _, track := range []bool{true, false} {
				fmt.Fprintf(&builder, "%s:\n  trackEvents: %t\n  variations:\n%s%s",
					FlagKey(sc, typ, track), track, variations(typ), scenarioBody(sc))
			}
		}
	}

	return builder.String()
}

// ManyFlagsYAML returns n simple flags named flag-0 .. flag-(n-1), mixing static, targeting and
// percentage flags, used for the all-flags benchmarks.
func ManyFlagsYAML(n int) string {
	var builder strings.Builder
	for i := range n {
		fmt.Fprintf(&builder, "flag-%d:\n  trackEvents: false\n  variations:\n    A: true\n    B: false\n", i)

		switch i % 3 {
		case 0:
			builder.WriteString("  defaultRule:\n    variation: A\n")
		case 1:
			fmt.Fprintf(
				&builder,
				"  targeting:\n    - query: key eq \"user-%d\"\n      variation: A\n  defaultRule:\n    variation: B\n",
				i,
			)
		default:
			builder.WriteString("  defaultRule:\n    percentage:\n      A: 50\n      B: 50\n")
		}
	}

	return builder.String()
}
